package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TarArchiveEntry_isFile_TriageGen0Test {

    private static final byte LF_OLDNORM = 1; // Assuming values based on common Tar constants
    private static final byte LF_NORMAL = 2;
    private static final byte LF_OTHER = 0;

    @Test
    public void testIsFile_WithFileObject_IsFile() {
        // Mocking a file object that returns true for isFile()
        // Since we can't easily mock File without PowerMock, 
        // we use a real temporary file if possible, or rely on the constructor.
        // However, the constructor TarArchiveEntry(File) is available.

        // Note: In a real environment, we'd use a temporary file.
        // For this test, we simulate the logic branch.
        File tempFile = new File("test_file_exists.txt");
        try {
            tempFile.createNewFile();
            TarArchiveEntry entry = new TarArchiveEntry(tempFile);
            assertTrue(entry.isFile());
        } catch (Exception e) {
            // Fallback if file system is restricted
        } finally {
            tempFile.delete();
        }
    }

    @Test
    public void testIsFile_WithFileObject_IsNotFile() {
        File tempDir = new File("test_dir_exists");
        try {
            tempDir.mkdir();
            TarArchiveEntry entry = new TarArchiveEntry(tempDir);
            assertFalse(entry.isFile());
        } catch (Exception e) {
            // Fallback
        } finally {
            tempDir.delete();
        }
    }

    @Test
    public void testIsFile_WithOldNormLinkFlag() {
        // Using constructor: TarArchiveEntry(String name, byte linkFlag)
        // We assume LF_OLDNORM is a valid byte value within the class context.
        // Since we can't access private fields, we use the constructor provided.
        // This test assumes the internal logic for linkFlag matches the constants.

        // We need to find a way to set the linkFlag. 
        // Based on the provided constructors:
        TarArchiveEntry entry = new TarArchiveEntry("linkName", (byte) 1); // Assuming 1 is LF_OLDNORM
        // If the constructor sets the flag, this will trigger the second if block.
        // Since we don't have the exact values for LF_OLDNORM, we use the logic provided in the snippet.
        // However, the snippet shows 'linkFlag == LF_OLDNORM'. 
        // In a real Triage, we'd use reflection if the constructor doesn't expose it.
    }

    /**
     * To ensure maximum coverage of the provided logic, we use reflection 
     * to set the private fields 'file' and 'linkFlag' since the constructors 
     * are the only way to initialize them.
     */
    @Test
    public void testIsFile_LinkFlag_OldNorm() throws Exception {
        TarArchiveEntry entry = new TarArchiveEntry("test");
        setPrivateField(entry, "linkFlag", (byte) 1); // LF_OLDNORM
        assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_LinkFlag_Normal() throws Exception {
        TarArchiveEntry entry = new TarArchiveEntry("test");
        setPrivateField(entry, "linkFlag", (byte) 2); // LF_NORMAL
        assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_NoFileNoLink_NotEndingWithSlash() {
        TarArchiveEntry entry = new TarArchiveEntry("regular_file");
        // file is null, linkFlag is not LF_OLDNORM/LF_NORMAL
        // getName() does not end with "/"
        assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_NoFileNoLink_EndingWithSlash() {
        TarArchiveEntry entry = new TarArchiveEntry("directory/");
        // file is null, linkFlag is not LF_OLDNORM/LF_NORMAL
        // getName() ends with "/"
        assertFalse(entry.isFile());
    }

    @Test
    public void testIsFile_NoFileNoLink_OtherLinkFlag() throws Exception {
        TarArchiveEntry entry = new TarArchiveEntry("test");
        setPrivateField(entry, "linkFlag", (byte) 0); 
        assertTrue(entry.isFile());
    }

    // Helper to access private fields for testing purposes
    private void setPrivateField(Object object, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = object.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(object, value);
    }
}
